WITH metrics AS (SELECT id, carrier, shipped_date, delivered_date, cost, LAST_VALUE(carrier, TRUE) OVER (PARTITION BY carrier ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier, CUME_DIST() OVER (PARTITION BY status ORDER BY cost NULLS FIRST) AS cost_cume_dist, LEAD(cost, 2, 0) OVER (ORDER BY delivered_date, id) AS next_cost FROM shipments) SELECT id, shipped_date, cost, last_known_carrier FROM metrics ORDER BY shipped_date DESC;
